namespace fs = std::filesystem;

namespace wavemix::core {

namespace {

constexpr std::string_view kHeader =
    "# Generated by WaveMix - do not edit, changes will be overwritten.\n"
    "# Add or remove channels in the WaveMix window instead.\n";

// Quotes a string for the PipeWire config format: "..." with \ and " escaped.
std::string conf_quote(std::string_view text)
{
    std::string out = "\"";
    for (char c : text) {
        if (c == '\\' || c == '"')
            out += '\\';
        out += c;
    }
    return out + "\"";
}

// object[key] if it's a string, else "". (operator[] on a const json is undefined
// behaviour for a missing key, hence the find.)
std::string string_field(const json& object, const std::string& key)
{
    const auto it = object.find(key);
    return it != object.end() && it->is_string() ? it->get<std::string>() : std::string();
}

}  // namespace

// Joins key=value pairs with spaces, quoting empty or spaced values and dropping quotes.
std::string pa_props(const PropList& props)
{
    std::string out;
    for (const auto& [key, raw] : props) {
        std::string value;
        for (char c : raw) {
            if (c != '\'' && c != '"')
                value += c;
        }
        if (!out.empty())
            out += ' ';
        const bool needs_quotes = value.empty() || value.find(' ') != std::string::npos;
        out += needs_quotes ? key + "='" + value + "'" : key + "=" + value;
    }
    return out;
}

// module-null-sink arguments: the sink name plus its description and wavemix.channel tag.
std::string sink_args(std::string_view sink_name, std::string_view description,
                      std::string_view channel_id)
{
    const PropList props{
        {"device.description", std::string(description)},
        // Marks the sink as WaveMix's, so it's never offered as a hardware output.
        {"wavemix.channel", std::string(channel_id)},
    };
    return "sink_name=" + std::string(sink_name) + " sink_properties=\"" + pa_props(props) + "\"";
}

// Builds the whole pipewire-pulse.conf.d file: one "load-module" entry per device and,
// with "pulse_routing" on, per loopback.
std::string render_login_conf(const json& config, const std::optional<std::string>& personal_output)
{
    // module name + arguments, in the order pipewire-pulse should run them: the Personal,
    // Stream and VOD Mixes (the Stream Mix always, so OBS never loses it), each channel's sink, WaveMix Mic, then with "pulse_routing" on
    // the loopbacks between them, once the sinks they read exist. The mic chain is the
    // service's (core/links.hpp).
    std::vector<std::pair<std::string, std::string>> commands;
    const auto found = config.find("channels");
    const json channels = found != config.end() && found->is_array() ? *found : json::array();
    // The Personal Mix is what you hear of the channels and of the mic's Monitor.
    const bool mic = mic_enabled(config);
    if (!channels.empty() || mic)
        commands.emplace_back("module-null-sink", sink_args(kPersonalSink, kPersonalLabel, ""));
    commands.emplace_back("module-null-sink", sink_args(kMixSink, kMixLabel, ""));
    if (vod_enabled(config))
        commands.emplace_back("module-null-sink", sink_args(kVodSink, kVodLabel, ""));
    for (const auto& channel : channels) {
        const std::string id = string_field(channel, "id");
        commands.emplace_back("module-null-sink",
                              sink_args(base_sink(id), string_field(channel, "label") + " (WaveMix)", id));
    }

    if (mic)
        for (auto& module : mic_device_modules())
            commands.push_back(std::move(module));
    for (auto& link : wanted_pulse_links(config, personal_output))
        commands.emplace_back("module-loopback", std::move(link.args));

    if (commands.empty())
        return std::string(kHeader) + "pulse.cmd = [ ]\n";
    std::string text = std::string(kHeader) + "pulse.cmd = [\n";
    for (const auto& [module, args] : commands) {
        // "nofail": one failed entry (an unplugged device, say) mustn't stop
        // pipewire-pulse from starting, or the user would have no audio at all.
        text += "    { cmd = \"load-module\" args = " + conf_quote(std::string(module) + " " + args) +
                " flags = [ \"nofail\" ] }\n";
    }
    return text + "]\n";
}

// Renders the login file and writes it only if its contents changed.
void write_login_conf(const Paths& paths, const json& config, const std::optional<std::string>& personal_output)
{
    const std::string text = render_login_conf(config, personal_output);
    // Unchanged, it's left alone: with "pulse_routing" on this runs whenever the output
    // device might have changed.
    if (std::ifstream in(paths.login_conf, std::ios::binary); in) {
        const std::string old((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
        if (old == text)
            return;
    }
    atomic_write_text(paths.login_conf, text);
}

}  // namespace wavemix::core
